INSERT INTO picture360_images (examId, specialty, conditionName, imageUrl, keyFeatures, examPearl, optionA, optionB, optionC, optionD, correctAnswer, explanation, status) VALUES
(1, 'Dermatology', 'Impetigo', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_impetigo-placeholder.webp', 'Golden-yellow crusted lesions, typically around the nose and mouth; may begin as vesicles or bullae that rupture leaving honey-coloured crust; highly contagious; common in children', 'Non-bullous impetigo is usually caused by Staphylococcus aureus. Bullous impetigo is always staphylococcal. First-line treatment is topical fusidic acid or hydrogen peroxide cream for localised disease; oral flucloxacillin for widespread', 'Staphylococcal or streptococcal superficial skin infection', 'Fungal infection requiring antifungal cream', 'Viral vesicular eruption', 'Autoimmune blistering disorder', 'A', 'Impetigo is a highly contagious superficial bacterial skin infection most commonly caused by Staphylococcus aureus or Group A Streptococcus. It presents with honey-coloured crusted lesions, typically perioral or perinasal. Treatment is topical fusidic acid for localised disease or oral flucloxacillin for widespread infection. Children should be excluded from school until lesions are crusted over or 48 hours after starting antibiotics.', 'active'),
(1, 'Dermatology', 'Herpes Zoster', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_herpes-zoster-placeholder.webp', 'Unilateral vesicular rash in a dermatomal distribution; painful grouped vesicles on an erythematous base; does not cross the midline; may involve thoracic, cervical, or trigeminal dermatomes', 'Herpes zoster is reactivation of varicella-zoster virus from dorsal root ganglia. Antivirals (aciclovir) should be started within 72 hours of rash onset. Hutchinson sign (vesicles on the nose tip) indicates nasociliary nerve involvement and risk of ophthalmic zoster', 'Reactivation of varicella-zoster virus in a dermatomal distribution', 'Primary varicella infection with widespread vesicles', 'Contact dermatitis from an irritant', 'Bacterial cellulitis with bullae formation', 'A', 'Herpes zoster (shingles) results from reactivation of latent varicella-zoster virus in the dorsal root ganglia. It presents as a painful unilateral vesicular rash confined to a single dermatome. Risk factors include immunosuppression and advancing age. Oral aciclovir should be started within 72 hours of rash onset. Post-herpetic neuralgia is the most common complication, particularly in the elderly.', 'active'),
(1, 'Dermatology', 'Herpes Simplex', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_herpes-simplex-placeholder.webp', 'Grouped vesicles on an erythematous base; typically perioral (HSV-1) or genital (HSV-2); painful with burning or tingling prodrome; may ulcerate and crust; recurrent episodes common', 'HSV-1 causes most orolabial herpes; HSV-2 causes most genital herpes but crossover occurs. Eczema herpeticum is a dermatological emergency in atopic patients. Aciclovir is first-line treatment', 'Herpes simplex virus infection with grouped vesicles', 'Aphthous ulceration from nutritional deficiency', 'Impetigo with honey-coloured crusting', 'Angular cheilitis from candidal infection', 'A', 'Herpes simplex virus causes recurrent grouped vesicles on an erythematous base, most commonly perioral (cold sores, HSV-1) or genital (HSV-2). A prodrome of tingling or burning often precedes the eruption. Treatment is oral aciclovir. Eczema herpeticum, where HSV disseminates in patients with atopic eczema, is a dermatological emergency requiring IV aciclovir.', 'active'),
(1, 'Dermatology', 'Molluscum Contagiosum', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_molluscum-placeholder.webp', 'Multiple small pearly dome-shaped papules with central umbilication; flesh-coloured or pink; typically 2-5mm diameter; common on trunk, axillae, and limbs in children; may be widespread in immunocompromised', 'Molluscum contagiosum is caused by a poxvirus. It is self-limiting in immunocompetent children, resolving within 12-18 months. Widespread or giant molluscum should prompt consideration of HIV testing', 'Poxvirus infection with umbilicated papules', 'Viral warts caused by human papillomavirus', 'Bacterial folliculitis', 'Insect bite reactions', 'A', 'Molluscum contagiosum is caused by a poxvirus and presents with characteristic pearly, dome-shaped papules with central umbilication. It is common in children and spread by direct skin contact. The condition is self-limiting in immunocompetent individuals, typically resolving within 12-18 months. No treatment is usually required, though cryotherapy or curettage may be offered if lesions are troublesome.', 'active'),
(1, 'Dermatology', 'Erythema Multiforme', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_erythema-multiforme-placeholder.webp', 'Target lesions with three concentric zones: central dusky area, pale oedematous ring, and peripheral erythematous halo; symmetrical distribution on extremities; palms and soles commonly involved; may affect mucous membranes', 'Erythema multiforme minor is most commonly triggered by herpes simplex virus. Erythema multiforme major involves mucous membranes. It is distinct from Stevens-Johnson syndrome which is drug-related and involves epidermal detachment', 'Immune-mediated reaction most commonly triggered by herpes simplex', 'Drug-induced toxic epidermal necrolysis', 'Urticarial vasculitis', 'Secondary syphilis', 'A', 'Erythema multiforme is an acute immune-mediated condition characterised by target lesions with three concentric zones. The most common trigger is herpes simplex virus (90% of cases), not drugs. It presents symmetrically on the extremities, particularly the palms and dorsal hands. Erythema multiforme minor is self-limiting; major involves mucous membranes. Treatment is supportive with management of the underlying trigger.', 'active'),
(1, 'Dermatology', 'Stevens-Johnson Syndrome', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_sjs-placeholder.webp', 'Widespread erythematous or purpuric macules with epidermal detachment affecting less than 10% body surface area; painful mucosal erosions involving at least two mucosal sites; Nikolsky sign positive; systemic features with fever and malaise', 'SJS is almost always drug-induced. Common culprits: allopurinol, carbamazepine, lamotrigine, phenytoin, sulfonamides, NSAIDs. It is a dermatological emergency requiring immediate drug withdrawal and supportive care, ideally in a burns unit. Mortality is 5-10%', 'Drug-induced mucocutaneous reaction with epidermal detachment', 'Severe erythema multiforme from herpes simplex', 'Staphylococcal scalded skin syndrome', 'Pemphigus vulgaris with mucosal involvement', 'A', 'Stevens-Johnson syndrome is a severe drug-induced mucocutaneous reaction with epidermal detachment affecting less than 10% BSA (10-30% is SJS-TEN overlap; over 30% is TEN). It involves painful erosions of at least two mucosal surfaces. Nikolsky sign is positive. The offending drug must be immediately withdrawn. Management is supportive in a specialist burns or dermatology unit. Mortality is 5-10% for SJS and up to 30% for TEN.', 'active'),
(1, 'Dermatology', 'Seborrhoeic Dermatitis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_seborrhoeic-dermatitis-placeholder.webp', 'Erythematous patches with greasy yellowish scale in sebaceous areas: scalp, nasolabial folds, eyebrows, behind ears, and central chest; dandruff is the mildest form; may flare with stress or illness', 'Seborrhoeic dermatitis is associated with Malassezia yeast. It is more common and severe in HIV-positive patients. Scalp treatment is ketoconazole shampoo; face and body respond to topical ketoconazole cream or mild topical steroids', 'Inflammatory dermatosis associated with Malassezia yeast in sebaceous areas', 'Psoriasis of the scalp', 'Tinea capitis with fungal infection', 'Allergic contact dermatitis', 'A', 'Seborrhoeic dermatitis is a chronic inflammatory condition affecting sebaceous-rich areas, associated with Malassezia yeast. It presents with erythematous patches and greasy yellowish scale on the scalp, nasolabial folds, eyebrows, and central chest. Dandruff (pityriasis capitis) is the mildest form. Treatment includes ketoconazole shampoo for the scalp and topical ketoconazole cream or mild corticosteroids for the face and body.', 'active'),
(1, 'Dermatology', 'Tinea Capitis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_tinea-capitis-placeholder.webp', 'Patchy alopecia with broken hair shafts giving a black dot appearance; scaling of the scalp; may have kerion formation (boggy inflammatory mass); posterior cervical lymphadenopathy; common in children', 'Tinea capitis requires oral antifungal treatment — topical agents do not penetrate the hair follicle. Griseofulvin or terbinafine are first-line. A kerion is a severe inflammatory response and is not an abscess — it should not be incised and drained', 'Dermatophyte fungal infection of the scalp requiring oral antifungals', 'Alopecia areata with autoimmune hair loss', 'Seborrhoeic dermatitis of the scalp', 'Trichotillomania with hair pulling', 'A', 'Tinea capitis is a dermatophyte infection of the scalp, most common in children. It presents with patchy alopecia, scaling, and broken hair shafts (black dot appearance). A kerion is a severe inflammatory variant presenting as a boggy tender mass. Topical antifungals are ineffective; oral griseofulvin or terbinafine is required. Household contacts should be screened and treated if symptomatic.', 'active'),
(1, 'Dermatology', 'Tinea Versicolor', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_tinea-versicolor-placeholder.webp', 'Multiple well-demarcated hypo- or hyperpigmented macules and patches on the trunk and proximal limbs; fine superficial scale; more noticeable after sun exposure when surrounding skin tans but affected areas do not', 'Pityriasis versicolor is caused by Malassezia furfur (a yeast, not a dermatophyte). Topical ketoconazole shampoo is first-line. Pigmentary changes may persist for months after successful treatment — this does not indicate treatment failure', 'Superficial yeast infection causing pigmentary changes', 'Post-inflammatory hypopigmentation from eczema', 'Vitiligo with autoimmune depigmentation', 'Morphoea with localised scleroderma', 'A', 'Pityriasis versicolor (tinea versicolor) is caused by the yeast Malassezia furfur. It presents with well-demarcated hypo- or hyperpigmented patches on the trunk with fine scale. It is more common in warm humid climates and in young adults. Treatment is topical ketoconazole shampoo applied as a body wash. Pigmentary changes may take months to resolve after successful eradication of the yeast.', 'active'),
(1, 'Dermatology', 'Onychomycosis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_onychomycosis-placeholder.webp', 'Thickened discoloured nail with subungual hyperkeratosis; yellow-brown discolouration; crumbling or brittle nail plate; usually begins at the distal free edge; toenails more commonly affected than fingernails', 'Nail clippings for mycology should be sent before starting treatment. Terbinafine is first-line oral treatment. Treatment duration is 6 weeks for fingernails and 3 months for toenails. Topical amorolfine nail lacquer may be used for mild distal disease', 'Dermatophyte fungal infection of the nail', 'Psoriatic nail dystrophy', 'Nail trauma with subungual haematoma', 'Lichen planus affecting the nail', 'A', 'Onychomycosis is a fungal infection of the nail, most commonly caused by dermatophytes (Trichophyton rubrum). It presents with thickened, discoloured, crumbling nails with subungual hyperkeratosis. Diagnosis should be confirmed with nail clippings for mycology before starting treatment. Oral terbinafine is first-line; treatment is 6 weeks for fingernails and 3 months for toenails. Topical amorolfine may suffice for mild distal disease.', 'active'),
(1, 'Dermatology', 'Pemphigus Vulgaris', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_pemphigus-vulgaris-placeholder.webp', 'Flaccid blisters that rupture easily leaving painful erosions; Nikolsky sign positive; oral mucosal erosions often the first presentation; widespread skin involvement; blisters are superficial and fragile', 'Pemphigus vulgaris involves IgG antibodies against desmoglein 3 (mucosal) and desmoglein 1 (skin). Biopsy shows intraepidermal split with acantholysis. Direct immunofluorescence shows intercellular IgG in a fishnet pattern. Treatment is systemic corticosteroids and steroid-sparing immunosuppressants', 'Autoimmune intraepidermal blistering disorder with anti-desmoglein antibodies', 'Bullous pemphigoid with subepidermal blisters', 'Stevens-Johnson syndrome from drug reaction', 'Dermatitis herpetiformis from coeliac disease', 'A', 'Pemphigus vulgaris is an autoimmune blistering disorder caused by IgG antibodies against desmogleins, causing intraepidermal acantholysis. It presents with flaccid blisters that rupture easily, leaving painful erosions. Oral mucosal involvement is often the first sign. Nikolsky sign is positive. Biopsy shows intraepidermal split; direct immunofluorescence shows intercellular IgG deposition. Treatment involves systemic corticosteroids and immunosuppressants such as azathioprine or mycophenolate.', 'active'),
(1, 'Dermatology', 'Pyoderma Gangrenosum', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_pyoderma-gangrenosum-placeholder.webp', 'Rapidly enlarging painful ulcer with violaceous undermined borders; necrotic base; often on the lower legs; may begin at sites of trauma (pathergy); associated with systemic disease', 'Pyoderma gangrenosum is a neutrophilic dermatosis. It is associated with inflammatory bowel disease (especially ulcerative colitis), rheumatoid arthritis, and haematological malignancies. It exhibits pathergy — worsening after surgical debridement. Treatment is immunosuppression, not surgery', 'Neutrophilic dermatosis associated with inflammatory bowel disease', 'Venous leg ulcer from chronic venous insufficiency', 'Infected diabetic foot ulcer', 'Squamous cell carcinoma presenting as an ulcer', 'A', 'Pyoderma gangrenosum is a neutrophilic dermatosis presenting with rapidly enlarging painful ulcers with violaceous undermined edges. It is associated with inflammatory bowel disease (especially UC), rheumatoid arthritis, and haematological malignancies. It exhibits pathergy — trauma or surgery worsens the condition. Diagnosis is clinical and by exclusion. Treatment is immunosuppressive (corticosteroids, ciclosporin), not surgical debridement.', 'active'),
(1, 'Dermatology', 'Erythema Nodosum', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_erythema-nodosum-placeholder.webp', 'Tender red nodules on the anterior shins; bilateral; lesions evolve through bruise-like colour changes (red to purple to yellow-green); no ulceration; may be accompanied by fever and arthralgia', 'Erythema nodosum is a panniculitis (inflammation of subcutaneous fat). Common causes: streptococcal infection, sarcoidosis, inflammatory bowel disease, drugs (OCP, sulfonamides), TB. It is the most common cause of pretibial nodules in young women', 'Septal panniculitis most commonly triggered by streptococcal infection or sarcoidosis', 'Deep vein thrombosis with superficial inflammation', 'Cellulitis of the lower legs', 'Vasculitis with palpable purpura', 'A', 'Erythema nodosum is a septal panniculitis presenting with tender red nodules on the anterior shins. Lesions evolve through bruise-like colour changes over 2-6 weeks without ulceration. Common causes include streptococcal infection (most common), sarcoidosis, inflammatory bowel disease, drugs (OCP, sulfonamides), and tuberculosis. Investigation should include throat swab, ASO titre, chest X-ray (sarcoidosis), and inflammatory markers. Treatment is of the underlying cause plus NSAIDs for symptomatic relief.', 'active'),
(1, 'Dermatology', 'Alopecia Areata', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_alopecia-areata-placeholder.webp', 'Well-circumscribed round or oval patches of non-scarring hair loss; smooth scalp without scaling or scarring; exclamation mark hairs at the periphery (short broken hairs that taper proximally); may affect beard, eyebrows, or eyelashes', 'Alopecia areata is autoimmune and associated with other autoimmune conditions (thyroid disease, vitiligo, pernicious anaemia). Exclamation mark hairs are pathognomonic. Most patches regrow spontaneously within 12 months. Poor prognostic factors include extensive disease, ophiasis pattern, and onset before puberty', 'Autoimmune non-scarring alopecia with exclamation mark hairs', 'Tinea capitis with fungal scalp infection', 'Trichotillomania from compulsive hair pulling', 'Androgenetic alopecia with male pattern baldness', 'A', 'Alopecia areata is an autoimmune condition causing well-circumscribed patches of non-scarring hair loss. Exclamation mark hairs (short hairs tapering at the base) at the patch margins are pathognomonic. It is associated with other autoimmune conditions including thyroid disease and vitiligo. Most patches regrow spontaneously within 12 months. Treatment options include topical or intralesional corticosteroids. Alopecia totalis (entire scalp) and universalis (entire body) are severe variants.', 'active'),
(1, 'Dermatology', 'Hidradenitis Suppurativa', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_hidradenitis-placeholder.webp', 'Recurrent painful nodules, abscesses, and sinus tracts in apocrine gland-bearing areas: axillae, groin, inframammary folds; double comedones (tombstone comedones); scarring and fibrosis from chronic disease; foul-smelling discharge', 'Hidradenitis suppurativa is a chronic inflammatory condition of the hair follicle, not a primary infection. Antibiotics (tetracyclines, clindamycin/rifampicin combination) are used for their anti-inflammatory properties. Biologics (adalimumab) are licensed for moderate-to-severe disease. Smoking and obesity are modifiable risk factors', 'Chronic inflammatory follicular occlusion disease of apocrine areas', 'Recurrent staphylococcal abscesses', 'Crohn disease with perianal fistulae', 'Lymphogranuloma venereum', 'A', 'Hidradenitis suppurativa is a chronic inflammatory condition of the hair follicle affecting apocrine gland-bearing areas. It presents with recurrent painful nodules, abscesses, and sinus tracts in the axillae, groin, and inframammary folds. Double comedones are characteristic. It is not primarily infectious. Management includes weight loss, smoking cessation, topical clindamycin, oral tetracyclines, and adalimumab for severe disease. Surgical excision may be needed for chronic sinus tracts.', 'active'),
(1, 'Dermatology', 'Actinic Keratosis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_actinic-keratosis-placeholder.webp', 'Rough scaly patches on sun-exposed skin; skin-coloured to erythematous; sandpaper-like texture on palpation; commonly on face, scalp (bald men), dorsal hands, and forearms; may have a cutaneous horn', 'Actinic keratoses are premalignant with a small risk (less than 10%) of transformation to squamous cell carcinoma. Treatment options include cryotherapy, topical 5-fluorouracil, topical imiquimod, or photodynamic therapy. Multiple actinic keratoses indicate significant cumulative UV damage', 'Premalignant dysplastic keratinocyte lesion from chronic UV exposure', 'Seborrhoeic keratosis (benign)', 'Basal cell carcinoma', 'Bowen disease (SCC in situ)', 'A', 'Actinic keratoses are premalignant lesions caused by chronic UV exposure, presenting as rough scaly patches on sun-exposed skin. They have a sandpaper-like texture on palpation. There is a small risk of progression to invasive squamous cell carcinoma. Treatment options include cryotherapy for isolated lesions, or field treatments (topical 5-fluorouracil, imiquimod, or photodynamic therapy) for multiple lesions. Sun protection advice is essential.', 'active'),
(1, 'Dermatology', 'Drug Rash Morbilliform', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_drug-rash-placeholder.webp', 'Widespread symmetrical erythematous maculopapular rash; often starts on the trunk and spreads to limbs; onset typically 7-14 days after starting a new drug; pruritic; spares palms and soles initially; no mucosal involvement', 'Morbilliform drug eruption is the most common type of drug rash. Common culprits: penicillins, cephalosporins, sulfonamides, allopurinol, anticonvulsants. The rash typically appears 7-14 days after starting the drug. Ampicillin rash in EBV infection is a classic example', 'Delayed-type hypersensitivity drug reaction', 'Viral exanthem from measles', 'Scarlet fever from Group A Streptococcus', 'Secondary syphilis', 'A', 'Morbilliform (exanthematous) drug eruption is the most common type of adverse cutaneous drug reaction. It presents with a widespread symmetrical maculopapular rash, typically appearing 7-14 days after starting a new medication. Common culprits include penicillins, cephalosporins, sulfonamides, and anticonvulsants. Management involves withdrawal of the offending drug and symptomatic treatment with emollients and antihistamines. The rash usually resolves within 1-2 weeks of drug cessation.', 'active'),
(1, 'Dermatology', 'Necrotising Fasciitis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_necrotising-fasciitis-placeholder.webp', 'Rapidly spreading erythema with severe pain disproportionate to clinical findings; dusky discolouration progressing to necrosis; crepitus may be present; systemic toxicity with fever, tachycardia, and hypotension; bullae and haemorrhagic blisters in advanced disease', 'Necrotising fasciitis is a surgical emergency. Pain out of proportion to clinical findings is the key early clue. Type I is polymicrobial; Type II is Group A Streptococcus (most common monomicrobial). Treatment is immediate surgical debridement plus IV broad-spectrum antibiotics. Mortality is 20-40%', 'Deep soft tissue infection requiring emergency surgical debridement', 'Severe cellulitis requiring IV antibiotics only', 'Deep vein thrombosis with skin changes', 'Gas gangrene from Clostridium perfringens', 'A', 'Necrotising fasciitis is a life-threatening deep soft tissue infection causing rapid destruction of fascia and subcutaneous tissue. The hallmark is pain disproportionate to clinical findings. It progresses rapidly from erythema to dusky discolouration, bullae, and necrosis. Crepitus suggests gas-forming organisms. It is a surgical emergency requiring immediate debridement and IV broad-spectrum antibiotics (e.g. meropenem, clindamycin, and linezolid). Mortality is 20-40% even with treatment.', 'active'),
(1, 'Dermatology', 'Keratoacanthoma', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_keratoacanthoma-placeholder.webp', 'Rapidly growing dome-shaped nodule with a central keratin-filled crater; smooth rolled edges; sun-exposed skin; grows rapidly over 2-3 weeks then may spontaneously involute over months; clinically indistinguishable from SCC', 'Keratoacanthoma is considered a well-differentiated variant of SCC by many authorities. Because it is clinically indistinguishable from SCC, excision biopsy is recommended. Rapid growth followed by spontaneous involution is the classic history but should not be relied upon to avoid biopsy', 'Rapidly growing keratinocyte tumour requiring excision to exclude SCC', 'Basal cell carcinoma with pearly rolled edges', 'Sebaceous cyst', 'Viral wart', 'A', 'Keratoacanthoma is a rapidly growing cutaneous tumour that presents as a dome-shaped nodule with a central keratin-filled crater on sun-exposed skin. It grows rapidly over weeks and may spontaneously involute over months. However, because it is clinically and sometimes histologically indistinguishable from squamous cell carcinoma, excision biopsy is recommended. Many dermatopathologists now classify keratoacanthoma as a well-differentiated variant of SCC.', 'active'),
(1, 'Dermatology', 'Kaposi Sarcoma', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/dermatology_kaposi-sarcoma-placeholder.webp', 'Violaceous or dark brown-red papules, plaques, or nodules; may be flat or raised; can occur on skin, mucous membranes, or visceral organs; lesions are non-blanching; commonly on the lower limbs, face, and oral mucosa', 'Kaposi sarcoma is caused by HHV-8 (human herpesvirus 8). The AIDS-related form is the most common type worldwide. In HIV-positive patients, it is an AIDS-defining illness. Treatment of the underlying HIV with antiretroviral therapy often leads to regression of KS lesions', 'Vascular tumour caused by HHV-8, associated with HIV/AIDS', 'Melanoma with pigmented nodules', 'Pyogenic granuloma', 'Bacillary angiomatosis from Bartonella', 'A', 'Kaposi sarcoma is a vascular neoplasm caused by human herpesvirus 8 (HHV-8). It presents with violaceous non-blanching papules, plaques, or nodules on the skin and mucous membranes. The AIDS-related form is the most common variant and is an AIDS-defining illness. Treatment includes antiretroviral therapy for HIV-associated KS, which often leads to lesion regression. Systemic chemotherapy may be required for extensive or visceral disease.', 'active');
